'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `sort` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasOwnProp( p, 'sort' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.sort ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.sort.call( value );
		};
	}
});

tape( 'the method throws an error if provided an argument which is not a function', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.sort( value );
		};
	}
});

tape( 'the method sorts a tuple in-place (default ascending)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 3, 1, 2 ] );

	t.deepEqual( p.orderedFields, [ 'x', 'y', 'z' ], 'returns expected value' );

	out = p.sort();

	t.strictEqual( out, p, 'returns expected value' );
	t.strictEqual( p[ 0 ], 1, 'returns expected value' );
	t.strictEqual( p[ 1 ], 2, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values remain unchanged:
	t.strictEqual( p.x, 3, 'returns expected value' );
	t.strictEqual( p.y, 1, 'returns expected value' );
	t.strictEqual( p.z, 2, 'returns expected value' );
	t.deepEqual( p.orderedFields, [ 'y', 'z', 'x' ], 'returns expected value' );
	t.end();
});

tape( 'the method sorts a tuple in-place (custom comparator)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 3, 2 ] );

	// Sort descending:
	out = p.sort( fcn );

	t.strictEqual( out, p, 'returns expected value' );
	t.strictEqual( p[ 0 ], 3, 'returns expected value' );
	t.strictEqual( p[ 1 ], 2, 'returns expected value' );
	t.strictEqual( p[ 2 ], 1, 'returns expected value' );

	t.end();

	function fcn( a, b ) {
		return b - a;
	}
});
